import catalog from './catalog.json';
import type {Unit,Pair} from '@/lib/types';
const pair=(vi:string,en:string):Pair=>({vi,en});
type Draft=[string,string,string,string,string?,string?];
// Original teaching drafts. Each unit has an example, a misconception and a formative check.
const drafts:Record<number,Draft[]>={
2:[
 ['Phương pháp kí hiệu đặt các dấu hiệu quy ước tại vị trí của đối tượng địa lí. Hình dạng, màu sắc và kích thước có thể thể hiện loại, đặc điểm hoặc quy mô đối tượng, nhưng phải được giải thích trong chú giải. Đọc vị trí trước, sau đó đối chiếu ý nghĩa kí hiệu để tránh suy đoán từ hình vẽ.','The symbol method places conventional signs at the locations of geographical features. Shape, colour and size can represent type, characteristics or magnitude when the legend defines them. First locate the symbol, then read its meaning in the legend.','Một tam giác có thể biểu hiện mỏ sắt nếu chú giải quy định như vậy. Tam giác lớn hơn chỉ có nghĩa là quy mô lớn hơn khi bản đồ có quy ước kích thước.','A triangle can represent an iron mine if the legend specifies this. A larger triangle indicates greater magnitude only when the map defines a size scale.'],
 ['Kí hiệu đường chuyển động biểu hiện sự di chuyển theo không gian. Mũi tên thường chỉ hướng, còn độ rộng có thể biểu thị quy mô dòng. Hãy kiểm tra đối tượng được vận chuyển, chiều đi và đơn vị trước khi so sánh các tuyến.','Flow lines represent movement through space. Arrows usually show direction, while line width may show the magnitude of a flow. Check what is moving, its direction and its unit before comparing routes.','Hai mũi tên cùng hướng nhưng khác độ rộng có thể biểu diễn hai luồng hàng hóa có khối lượng khác nhau.','Two arrows pointing in the same direction but with different widths may represent freight flows of different sizes.'],
 ['Phương pháp chấm điểm dùng mỗi chấm để biểu hiện một lượng quy ước của đối tượng. Tổng lượng được tính bằng số chấm nhân với giá trị một chấm. Vị trí các chấm thể hiện sự phân bố theo mức khái quát của bản đồ, không nhất thiết là vị trí chính xác của từng cá thể.','The dot method assigns a fixed quantity to each dot. Total quantity equals the number of dots multiplied by the dot value. Dot positions show a generalised distribution and need not locate individual people or objects precisely.','6000 người cần 60 chấm nếu mỗi chấm bằng 100 người, hoặc 30 chấm nếu mỗi chấm bằng 200 người. Tổng dân số không đổi.','A population of 6,000 requires 60 dots at 100 people per dot, or 30 dots at 200 people per dot. The total population stays the same.'],
 ['Phương pháp bản đồ biểu đồ đặt biểu đồ tại các đơn vị lãnh thổ để thể hiện quy mô, cơ cấu hoặc sự thay đổi của đối tượng. Khi so sánh, cần đọc cùng một quy ước kích thước và các thành phần trong chú giải. Bản đồ cho biết ở đâu, biểu đồ bổ sung bao nhiêu và gồm những gì.','Cartodiagrams place charts within territorial units to show magnitude, composition or change. Comparisons require a consistent size scale and a shared legend. The map shows where; the chart adds how much and what components are present.','Biểu đồ tròn đặt trên các vùng có thể cho biết cơ cấu ba ngành. Diện tích hình tròn chỉ dùng để so quy mô khi đã có thang đo.','Pie charts placed over regions can show the shares of three sectors. Circle area can compare totals only when an explicit scale is supplied.']
],
3:[
 ['Sử dụng bản đồ bắt đầu từ việc xác định mục đích và chọn bản đồ phù hợp. Đọc tên, phạm vi, tỉ lệ, phương hướng, chú giải và thời điểm dữ liệu trước khi trả lời câu hỏi. Kết hợp các lớp thông tin để đưa ra nhận xét có dẫn chứng.','Using a map starts with a purpose and a suitable map. Read its title, extent, scale, orientation, legend and data date before answering a question. Combine information from relevant layers to support your interpretation.','Tìm nơi tham quan cần bản đồ đường đi; tìm sự phân bố lượng mưa cần bản đồ chuyên đề khí hậu.','Planning a visit requires a route map; investigating rainfall distribution requires a thematic climate map.'],
 ['GPS hỗ trợ xác định vị trí từ tín hiệu của các vệ tinh. Máy thu khai thác thời gian truyền tín hiệu và thông tin quỹ đạo để ước tính vị trí; điều kiện thu tín hiệu có thể làm thay đổi độ chính xác. GPS, bản đồ số và thuật toán tìm đường là những thành phần khác nhau.','GPS supports positioning using satellite signals. A receiver uses signal travel time and orbital information to estimate its position; reception conditions affect accuracy. GPS, a digital map and a routing algorithm are different components.','Ở gần nhà cao tầng, tín hiệu có thể bị che khuất hoặc phản xạ. Điểm vị trí trên bản đồ vì vậy cần được hiểu kèm khả năng sai số.','Near tall buildings, signals can be blocked or reflected. A position marker should therefore be interpreted with its possible uncertainty.'],
 ['Bản đồ số lưu trữ và hiển thị thông tin không gian bằng các lớp dữ liệu. Tọa độ xác định vị trí theo một hệ quy chiếu; vĩ độ và kinh độ không thể đổi chỗ tùy ý. Khi chia sẻ một điểm, cần kiểm tra thứ tự tọa độ và quy ước của ứng dụng.','Digital maps store and display spatial information in data layers. Coordinates locate a place within a reference system; latitude and longitude are not interchangeable. Check coordinate order and the application’s convention when sharing a point.','Một điểm ở 21°B, 106°Đ có vĩ độ Bắc và kinh độ Đông. Dấu và thứ tự tọa độ phải theo đúng hướng dẫn của công cụ.','A point at 21°N, 106°E has north latitude and east longitude. Coordinate signs and order must follow the tool’s convention.'],
 ['Tìm đường cần một tiêu chí cụ thể như quãng đường ngắn, thời gian ít hoặc tuyến phù hợp phương tiện. Tuyến ngắn nhất chưa chắc nhanh nhất vì tốc độ và điều kiện giao thông khác nhau. Người học vẫn có thể luyện đọc bản đồ bằng vị trí giả lập khi không chia sẻ vị trí thật.','Route planning needs a criterion such as shortest distance, least time or suitability for a vehicle. The shortest route is not necessarily the fastest because speeds and traffic conditions vary. Simulated positions allow map practice without sharing a real location.','Tuyến 4 km mất 20 phút, tuyến 6 km mất 12 phút. Theo dữ liệu này, tuyến dài hơn lại nhanh hơn; kết luận cần cập nhật nếu điều kiện thay đổi.','A 4 km route takes 20 minutes and a 6 km route takes 12 minutes. In this dataset, the longer route is faster; the conclusion may change with conditions.']
],
4:[
 ['Trái Đất hình thành trong quá trình phát triển của Hệ Mặt Trời từ vật chất ban đầu, qua tích tụ và va chạm. Trong giai đoạn sớm, nhiệt và sự phân dị vật chất góp phần tạo nên cấu trúc bên trong. Mô hình trình bày trình tự khái quát, không thể xem như đoạn phim quan sát trực tiếp lịch sử Trái Đất.','Earth formed during the development of the Solar System through the accumulation and collision of material. Early heating and differentiation contributed to its internal structure. The model presents a broad sequence rather than a directly observed film of Earth’s history.','Các hình theo giai đoạn giúp thảo luận sự tích tụ, nóng lên và phân lớp; thời gian của hoạt ảnh không phải thời gian địa chất thực.','A sequence of diagrams helps discuss accretion, heating and layering; animation time is not actual geological time.'],
 ['Vỏ Trái Đất là lớp ngoài cùng của phần rắn Trái Đất. Vỏ lục địa và vỏ đại dương khác nhau về chiều dày, thành phần và đặc điểm cấu tạo. Khi đọc mặt cắt, cần phân biệt ranh giới thật với phần chiều dày đã được phóng đại để dễ nhìn.','Earth’s crust is the outermost layer of the solid Earth. Continental and oceanic crust differ in thickness, composition and structure. In a cross-section, distinguish actual boundaries from exaggerated thickness used for visibility.','Sơ đồ có thể vẽ vỏ dày hơn tương quan thực. Muốn so chiều dày phải dùng số liệu và thang tỉ lệ, thay vì đo trên hình minh họa.','A diagram may exaggerate crustal thickness. Compare thickness using data and scales rather than measuring an illustrative drawing.'],
 ['Khoáng vật là những thành phần tự nhiên có đặc tính vật lí và thành phần nhất định; nhiều loại đá được tạo bởi một hoặc nhiều khoáng vật. Đá là tập hợp vật liệu hình thành qua những quá trình địa chất. Không nên chỉ dựa vào màu của ảnh để phân biệt khoáng vật và đá.','Minerals are natural constituents with characteristic properties and composition; many rocks contain one or more minerals. Rocks are aggregates formed through geological processes. Image colour alone is insufficient to distinguish minerals and rocks.','Quan sát mẫu đá cần kết hợp thành phần, cấu tạo và bối cảnh hình thành. Một ảnh chụp dưới ánh sáng khác có thể cho màu khác.','A rock sample is studied through its composition, texture and formation context. Different lighting may change its apparent colour in a photograph.'],
 ['Ba nhóm đá cơ bản là magma, trầm tích và biến chất. Đá magma gắn với sự nguội và kết tinh vật chất nóng chảy; đá trầm tích gắn với tích tụ và các quá trình tạo đá; đá biến chất gắn với biến đổi trong điều kiện nhiệt và áp suất. Những nhóm này có thể tham gia một chu trình biến đổi lâu dài.','The three main rock groups are igneous, sedimentary and metamorphic. Igneous rocks form as molten material cools and crystallises; sedimentary rocks involve deposition and rock-forming processes; metamorphic rocks change under heat and pressure. Rocks can participate in long-term cycles of transformation.','Một mẫu chịu nhiệt và áp suất nhưng không nóng chảy hoàn toàn có thể mang dấu hiệu biến chất; cần thêm bằng chứng để phân loại chắc chắn.','A sample altered by heat and pressure without complete melting may show metamorphism; additional evidence is needed for confident classification.']
],
5:[
 ['Trái Đất tự quay quanh trục theo hướng từ tây sang đông. Do Trái Đất có dạng gần cầu và chỉ một phía được Mặt Trời chiếu sáng tại một thời điểm, một địa điểm lần lượt đi qua phần sáng và phần tối. Đây là cơ chế tạo sự luân phiên ngày và đêm.','Earth rotates on its axis from west to east. Because Earth is approximately spherical and only one side faces sunlight at a time, a location alternates between the illuminated and dark sides. This produces the cycle of day and night.','Giữ nguồn sáng cố định, xoay quả địa cầu và theo dõi một điểm đánh dấu. Điểm đó lần lượt sáng rồi tối dù nguồn sáng không quay quanh nó.','Keep a light source fixed, rotate a globe and track one marked location. The point alternates between light and darkness without the light orbiting it.'],
 ['Trái Đất chuyển động quanh Mặt Trời đồng thời vẫn tự quay. Trục nghiêng giữ hướng gần ổn định trong quá trình chuyển động quỹ đạo ở mô hình học tập. Cần phân biệt chuyển động quanh Mặt Trời với chuyển động tự quay vì hai chuyển động dẫn tới những hệ quả khác nhau.','Earth orbits the Sun while rotating on its axis. In the teaching model, the tilted axis maintains an approximately fixed direction during the orbit. Orbital motion and rotation must be distinguished because they produce different geographical effects.','Chế độ quan sát từ bên ngoài giúp thấy quỹ đạo; chế độ theo một điểm trên Trái Đất giúp thấy sự thay đổi chiếu sáng.','An external viewpoint reveals the orbit; tracking a location on Earth reveals changes in illumination.'],
 ['Giờ địa phương theo Mặt Trời thay đổi theo kinh độ; các nơi phía đông có giờ sớm hơn phía tây trong cách tính cơ bản. Giờ múi là quy ước để tổ chức sinh hoạt và có thể theo ranh giới hành chính. Khi tính giờ theo UTC, cộng hoặc trừ độ lệch rồi kiểm tra việc chuyển ngày.','Local solar time varies with longitude; eastern locations are ahead of western locations in the basic model. Standard time zones are conventions and may follow administrative boundaries. For UTC calculations, apply the offset and check whether the date changes.','UTC là 08:00 thì UTC+7 là 15:00 cùng ngày. Nếu phép cộng vượt 24 giờ, phải chuyển sang ngày tiếp theo.','When UTC is 08:00, UTC+7 is 15:00 on the same date. An addition past 24:00 requires moving to the following date.'],
 ['Các mùa chủ yếu gắn với trục nghiêng và sự thay đổi chiếu sáng khi Trái Đất chuyển động quanh Mặt Trời. Hai bán cầu có sự phân hóa mùa đối lập. Góc chiếu và độ dài thời gian chiếu sáng cùng ảnh hưởng lượng năng lượng nhận được; không giải thích mùa chỉ bằng khoảng cách tới Mặt Trời.','Seasons mainly arise from axial tilt and changing illumination as Earth orbits the Sun. The hemispheres experience opposite seasonal patterns. Sun angle and daylight duration both affect received energy; distance from the Sun alone does not explain seasons.','So sánh trục nghiêng 23,5° và trục không nghiêng tại cùng vị trí quỹ đạo. Trong mô hình, sự khác biệt mùa do trục nghiêng giảm hoặc mất khi đặt góc nghiêng bằng 0°.','Compare a 23.5° tilt with no tilt at the same orbital position. In the model, seasonality caused by tilt decreases or disappears when tilt is set to 0°.']
],
6:[
 ['Thạch quyển gồm vỏ Trái Đất và phần trên cứng của lớp phủ. Nó được phân chia thành các mảng có thể chuyển động tương đối. Khái niệm thạch quyển vì vậy rộng hơn khái niệm vỏ Trái Đất.','The lithosphere comprises Earth’s crust and the rigid uppermost mantle. It is divided into plates that move relative to one another. The lithosphere is therefore not the same as the crust alone.','Đọc mặt cắt cần tìm cả vỏ và phần lớp phủ cứng phía dưới, thay vì chỉ chọn lớp mỏng ngoài cùng.','In a cross-section, identify both the crust and the rigid mantle beneath it rather than selecting only the outermost layer.'],
 ['Mảng kiến tạo có thể chứa phần lục địa, phần đại dương hoặc cả hai. Ranh giới mảng không trùng hoàn toàn với đường bờ biển. Bản đồ các mảng là mô hình khái quát cần được đọc cùng chú giải và mức độ chi tiết.','A tectonic plate can include continental areas, oceanic areas or both. Plate boundaries do not simply follow coastlines. Plate maps are generalisations that require attention to their legends and level of detail.','Một mảng không nhất thiết chỉ nằm dưới một châu lục. Hãy bật riêng đường bờ và ranh giới mảng để đối chiếu.','A plate need not lie beneath a single continent. Compare coastlines and plate boundaries as separate layers.'],
 ['Ba kiểu ranh giới cơ bản là phân kì, hội tụ và trượt bằng. Phân kì có hai mảng tách nhau; hội tụ có hai mảng xích lại; trượt bằng có chuyển động ngang tương đối. Loại vật liệu và bối cảnh quyết định cơ chế cụ thể, đặc biệt trong các trường hợp hội tụ.','The three basic boundary types are divergent, convergent and transform. Plates separate at divergent boundaries, approach at convergent boundaries and slide laterally at transform boundaries. Plate material and context shape the specific mechanism, especially during convergence.','Hội tụ đại dương–lục địa có thể có hút chìm; va chạm hai lục địa gắn với biến dạng và nâng núi, không tự động tạo cùng một kiểu núi lửa.','Ocean–continent convergence may involve subduction. Continental collision produces deformation and mountain building, rather than automatically creating the same volcanic pattern.'],
 ['Chuyển động mảng liên quan đến sự hình thành địa hình, động đất và nhiều hoạt động núi lửa. Các hệ quả có quan hệ với kiểu ranh giới nhưng không phải mọi hiện tượng đều nằm đúng trên một đường ranh giới được vẽ. Dữ liệu phân bố giúp nhận diện xu hướng và ngoại lệ.','Plate motion is related to landform development, earthquakes and much volcanic activity. Effects depend on boundary type, but not every event lies exactly on a mapped boundary line. Distribution data help reveal both patterns and exceptions.','Động đất thường tập trung thành dải; một số núi lửa nội mảng cho thấy không thể dùng từ “mọi” để mô tả tất cả vị trí núi lửa.','Earthquakes often cluster in belts; some intraplate volcanoes show why an absolute statement about all volcano locations is inappropriate.']
],
7:[
 ['Nội lực có nguồn gốc từ năng lượng bên trong Trái Đất và tác động đến cấu trúc, vận động của vỏ. Các quá trình có thể gây nâng, hạ, uốn nếp hoặc đứt gãy theo điều kiện cụ thể. Không nên quy mọi tác động nội lực thành một dạng địa hình duy nhất.','Internal forces originate from energy within Earth and affect crustal structure and movement. Processes can cause uplift, subsidence, folding or faulting under different conditions. Internal activity does not produce a single universal landform.','Trong mô hình, nâng một khối địa hình làm thay đổi độ dốc ban đầu, từ đó ảnh hưởng đường đi của dòng chảy.','In the model, uplifting a terrain block changes its initial slope and can affect the paths of runoff.'],
 ['Ngoại lực tác động trên hoặc gần bề mặt Trái Đất, gắn với các tác nhân như nước, gió, băng và sinh vật. Năng lượng Mặt Trời và trọng lực có vai trò quan trọng. Ngoại lực vừa có thể phá hủy, vừa có thể tích tụ vật liệu để tạo địa hình mới.','External forces act on or near Earth’s surface through agents such as water, wind, ice and organisms. Solar energy and gravity are important. External processes can both remove material and deposit it to create landforms.','Một dòng sông có thể bóc mòn ở đoạn này và bồi tụ ở đoạn khác. Vì vậy không thể nói ngoại lực chỉ phá hủy.','A river can erode one reach and deposit sediment in another. External processes therefore do more than destroy landforms.'],
 ['Phong hóa làm biến đổi hoặc phá hủy đá tại chỗ; bóc mòn lấy vật liệu khỏi vị trí ban đầu. Hai quá trình có liên hệ nhưng không đồng nghĩa. Mức tác động phụ thuộc vật liệu, khí hậu, địa hình và sự che phủ.','Weathering breaks down or alters rock in place; erosion removes material from its original position. The processes are related but distinct. Their intensity depends on material, climate, topography and cover.','Đá nứt vỡ tại sườn là biểu hiện phong hóa; các mảnh bị nước cuốn đi liên quan đến bóc mòn và vận chuyển.','Rock fracturing on a slope illustrates weathering; fragments carried away by water involve erosion and transport.'],
 ['Vận chuyển đưa vật liệu từ nơi này tới nơi khác; bồi tụ xảy ra khi vật liệu được tích lũy. Khả năng mang vật liệu của tác nhân vận chuyển thay đổi theo điều kiện. Các quá trình phong hóa, bóc mòn, vận chuyển và bồi tụ có thể diễn ra đồng thời ở những vị trí khác nhau.','Transport moves material between locations; deposition accumulates it. An agent’s ability to carry sediment changes with conditions. Weathering, erosion, transport and deposition can occur simultaneously in different places.','Khi dòng chảy giảm khả năng mang vật liệu, một phần trầm tích có thể lắng lại. Mô hình chỉ thể hiện xu hướng, không dự báo số tấn đất thực tế.','When a flow loses carrying capacity, some sediment may settle. The model shows a tendency rather than predicting actual tonnes of soil loss.']
],
8:[
 ['Đọc bản đồ động đất cần xác định phạm vi, khoảng thời gian, ngưỡng ghi nhận và chú giải. Mỗi điểm thuộc một tập dữ liệu có giới hạn. Không có điểm trong một bộ lọc chỉ có nghĩa là chưa có sự kiện phù hợp trong tập đang xem.','Reading an earthquake map requires its extent, time window, recording threshold and legend. Each point belongs to a limited dataset. An empty filter means that no matching events occur in that dataset, not that a location has no hazard.','So sánh bản đồ một tháng với bản đồ nhiều năm mà không kiểm thời gian có thể dẫn tới nhận xét sai.','Comparing a one-month map with a multi-year map without checking the time windows can produce misleading conclusions.'],
 ['Sự phân bố núi lửa cần được đọc từ vị trí, loại đối tượng và trạng thái dữ liệu của nguồn. Nhiều núi lửa liên hệ với ranh giới mảng, nhưng có ngoại lệ nội mảng. Không tự ý xóa điểm chỉ vì điểm đó không phù hợp một nhận định khái quát.','Volcano distribution should be read using location, feature type and the source’s data definitions. Many volcanoes are related to plate boundaries, but intraplate exceptions exist. Do not remove points simply because they challenge a generalisation.','Bật lớp núi lửa rồi lớp ranh giới để tìm vùng tập trung và các điểm ở xa ranh giới hiển thị.','Turn on volcano and boundary layers to identify clusters and points away from displayed boundaries.'],
 ['Đối chiếu ranh giới mảng với động đất và núi lửa cần các lớp có phạm vi và hệ tọa độ tương thích. Quan sát vùng tập trung và khoảng cách tương đối giúp mô tả mối liên hệ. Đường trên bản đồ khái quát không thể hiện toàn bộ chiều rộng vùng biến dạng.','Comparing boundaries with earthquakes and volcanoes requires compatible extents and coordinate systems. Clusters and relative distances help describe spatial relationships. A line on a generalised map does not represent the entire width of a deformation zone.','Chọn hai vùng khác nhau, ghi lớp đã bật và nêu dẫn chứng cụ thể thay vì chỉ nhận xét “nhiều điểm”.','Choose two regions, record the enabled layers and cite specific evidence rather than merely saying there are many points.'],
 ['Nhận xét địa lí cần chỉ ra vị trí, xu hướng và bằng chứng, đồng thời nêu giới hạn của dữ liệu. Bản đồ phân bố cho thấy quan hệ không gian; bản thân việc trùng vị trí chưa đủ cho mọi kết luận nhân quả hoặc dự báo. Mô hình minh họa trong bài không thay bản đồ nguy cơ chính thức.','A geographical interpretation should identify locations, patterns, evidence and data limitations. Distribution maps reveal spatial relationships; co-location alone does not establish every causal claim or prediction. The teaching illustration does not replace an official hazard map.','Một nhận xét tốt gồm vùng quan sát, hiện tượng, dẫn chứng và một điều chưa thể kết luận từ tập dữ liệu.','A strong interpretation states the region, phenomenon, evidence and one conclusion the dataset cannot support.']
],
9:[
 ['Khí quyển là lớp không khí bao quanh Trái Đất và có cấu trúc thay đổi theo độ cao. Các tầng được phân chia theo những đặc điểm nhất định, không phải các vách ngăn kín. Phần lớn hiện tượng thời tiết quen thuộc diễn ra trong tầng đối lưu.','The atmosphere is the gaseous layer surrounding Earth, with properties that vary with altitude. Layers are defined by particular characteristics rather than sealed boundaries. Most familiar weather occurs in the troposphere.','Khi đọc sơ đồ tầng khí quyển, kiểm tra trục độ cao và chú ý phần tỉ lệ đã được giản lược.','When reading an atmospheric-layer diagram, check the altitude axis and any simplified scaling.'],
 ['Nhiệt độ không khí biểu thị mức nóng lạnh của không khí và biến đổi theo thời gian, vĩ độ, độ cao cùng điều kiện bề mặt. Nhiệt độ trung bình và biên độ nhiệt là các chỉ số khác nhau. Dùng cùng đơn vị và cùng khoảng thời gian khi so sánh.','Air temperature expresses how warm or cold the air is and varies with time, latitude, elevation and surface conditions. Mean temperature and temperature range are different measures. Comparisons require matching units and periods.','Biên độ nhiệt năm lấy nhiệt độ trung bình tháng cao nhất trừ tháng thấp nhất, không phải cộng tất cả các tháng.','Annual temperature range is the highest mean monthly temperature minus the lowest, not the sum of all months.'],
 ['Khí áp là áp suất của không khí; sự chênh lệch khí áp góp phần tạo chuyển động không khí. Trong thí nghiệm lí tưởng bỏ qua sự quay và ma sát, gió được mô tả từ áp cao tới áp thấp. Gió thực chịu thêm các lực và điều kiện địa phương nên có thể đổi hướng.','Air pressure is the pressure exerted by air; pressure differences help drive air movement. In an idealised experiment without rotation or friction, wind moves from high to low pressure. Real winds respond to additional forces and local conditions.','Đảo hai vùng 1020 và 1000 hPa trong thí nghiệm sẽ đảo vector gió, trong khi các điều kiện còn lại được giữ nguyên.','Reversing regions at 1020 and 1000 hPa reverses the experimental wind vector while other conditions are held constant.'],
 ['Độ ẩm liên quan lượng hơi nước trong không khí; mây hình thành khi có điều kiện ngưng tụ thích hợp. Mưa còn cần quá trình phát triển hạt nước hoặc tinh thể để rơi xuống. Không thể kết luận cứ độ ẩm cao là chắc chắn có mưa ngay.','Humidity concerns water vapour in the air; clouds form under suitable condensation conditions. Precipitation also requires droplets or ice particles to develop sufficiently to fall. High humidity does not guarantee immediate rain.','Theo dõi một khối khí được nâng lên: nhiệt độ và điều kiện bão hòa thay đổi, nhưng kết quả phụ thuộc các giả định của thí nghiệm.','Track a rising air parcel: temperature and saturation conditions change, but the outcome depends on the experiment’s assumptions.'],
 ['Khí hậu chịu tác động phối hợp của vĩ độ, độ cao, địa hình, vị trí lục địa–đại dương và các quá trình tuần hoàn. Một yếu tố đơn lẻ thường không giải thích đầy đủ đặc điểm của một nơi. Cần kết hợp dữ liệu và điều kiện không gian.','Climate reflects combined influences including latitude, elevation, relief, land–ocean position and circulation. A single factor seldom explains a location completely. Data should be considered together with spatial context.','Hai nơi cùng vĩ độ có thể khác khí hậu do độ cao hoặc ảnh hưởng biển khác nhau.','Two places at the same latitude may have different climates because of elevation or maritime influence.'],
 ['Nhiệt độ, khí áp, gió, độ ẩm và mưa có quan hệ trong hệ thống khí quyển. Khi khảo sát một quan hệ bằng mô hình, cần giữ các biến khác hoặc ghi rõ điều kiện thay đổi. Thời tiết mô tả trạng thái ngắn hạn; khí hậu gắn với đặc điểm lâu dài.','Temperature, pressure, wind, humidity and precipitation interact within the atmosphere. Model experiments should hold other variables fixed or document their changes. Weather concerns short-term conditions, whereas climate describes long-term characteristics.','Thay nhiều tham số cùng lúc có thể cho một kết quả khác nhưng chưa cho biết riêng tham số nào gây nên thay đổi.','Changing several parameters simultaneously may alter the outcome but does not isolate the effect of any single parameter.']
],
10:[
 ['Bản đồ các đới khí hậu khái quát sự phân bố khí hậu theo một hệ phân loại. Cần đọc chú giải, ranh giới và nguồn trước khi xác định đới của một địa điểm. Ranh giới trên bản đồ có thể được giản lược và không có nghĩa điều kiện thay đổi đột ngột tại một đường mảnh.','Climate-zone maps generalise spatial patterns within a classification system. Read the legend, boundaries and source before locating a climate zone. Generalised boundary lines do not imply abrupt physical changes along a narrow line.','Chọn một vùng, đọc tên đới trong chú giải rồi đối chiếu đặc điểm nhiệt và mưa, thay vì chỉ nhớ màu.','Choose a region, read its climate-zone label and compare temperature and rainfall rather than relying on colour alone.'],
 ['Kiểu khí hậu được nhận diện qua sự kết hợp chế độ nhiệt, lượng mưa, phân bố mùa và vị trí. Hai trạm có cùng tổng mưa năm vẫn có thể khác mùa mưa hoặc chế độ nhiệt. Kết luận phân loại cần theo tiêu chí đã được chọn.','Climate types are identified from temperature, rainfall totals, seasonality and location together. Stations with equal annual rainfall can still differ in rainy seasons or thermal regimes. Classification must follow an explicit set of criteria.','Một trạm mưa đều quanh năm và một trạm mưa tập trung mùa hạ có thể cùng tổng năm nhưng không giống chế độ mưa.','A station with year-round rainfall and one with summer-concentrated rain can have the same annual total but different rainfall regimes.'],
 ['Biểu đồ khí hậu thường kết hợp đường nhiệt độ với cột lượng mưa. Hai trục có đơn vị riêng, không được đọc lẫn. Tổng mưa năm là tổng 12 tháng; biên độ nhiệt là hiệu cực đại và cực tiểu. Tháng thiếu dữ liệu phải được phân biệt với giá trị bằng 0.','A climograph commonly combines a temperature line with rainfall bars. The axes have distinct units. Annual rainfall is the sum of 12 monthly totals, while temperature range is the difference between maximum and minimum monthly temperatures. Missing data are not zero.','Bộ A minh họa có biên độ nhiệt 28−20=8°C và tổng mưa 1340 mm. Đây là dữ liệu tự dựng để luyện thao tác.','Illustrative dataset A has a temperature range of 28−20=8°C and annual rainfall of 1,340 mm. It is synthetic practice data.'],
 ['So sánh khí hậu cần dùng cùng khoảng thời gian và cùng cách tính chỉ số. Hãy mô tả mức nhiệt, biên độ, tổng mưa và mùa mưa, sau đó nêu điểm giống và khác. Không gán tên một trạm thật cho bộ số liệu tự dựng.','Climate comparisons require matching periods and consistent calculations. Describe temperature level, range, rainfall total and seasonality before identifying similarities and differences. A synthetic dataset must not be presented as a real station record.','Khi so A và B, ghi ít nhất hai dẫn chứng từ bảng hoặc biểu đồ và một giới hạn của kết luận.','When comparing A and B, cite at least two observations from the table or chart and one limitation of the conclusion.']
],
11:[
 ['Thủy quyển bao gồm nước trên Trái Đất trong các dạng tồn tại và các kho khác nhau. Biển, đại dương, sông, hồ, băng, nước ngầm và hơi nước có liên hệ qua các quá trình trao đổi. Quan sát một kho riêng lẻ chưa đủ để hiểu toàn bộ hệ thống.','The hydrosphere includes Earth’s water in different forms and reservoirs. Oceans, rivers, lakes, ice, groundwater and water vapour are connected through exchanges. Studying one reservoir alone does not explain the whole system.','Theo dõi một giọt nước từ mặt biển tới khí quyển rồi về lục địa để nhận diện các kho và quá trình.','Follow a water parcel from the sea to the atmosphere and then to land to identify reservoirs and processes.'],
 ['Vòng tuần hoàn nước là sự vận động liên tục giữa các kho qua bốc hơi, ngưng tụ, mưa, thấm và dòng chảy. Năng lượng Mặt Trời và trọng lực có vai trò quan trọng. Nước bốc hơi chuyển sang khí quyển, không biến mất khỏi hệ thống.','The water cycle moves water between reservoirs through evaporation, condensation, precipitation, infiltration and flow. Solar energy and gravity are important drivers. Evaporated water enters the atmosphere rather than disappearing from the system.','Giảm khả năng thấm trong mô hình có thể làm tăng phần chảy tràn và giảm bổ sung nước ngầm khi giữ lượng mưa.','With rainfall held constant, reducing infiltration in the model can increase runoff and decrease groundwater recharge.'],
 ['Sông là dòng nước chảy theo lòng dẫn; hồ là kho nước nằm trong vùng trũng; nước ngầm tồn tại trong lỗ hổng và khe nứt của vật liệu dưới đất. Các dạng này có thể trao đổi với nhau. Không nên hình dung mọi nước ngầm như một biển nước trống rỗng liên tục.','Rivers flow through channels, lakes store water in depressions, and groundwater occupies pores and fractures below ground. These stores can exchange water. Groundwater should not generally be imagined as one continuous underground open sea.','Một phần nước sông có thể được bổ sung từ nước ngầm, đặc biệt khi các điều kiện lưu vực cho phép.','Groundwater can contribute to river flow where catchment conditions allow this exchange.'],
 ['Chế độ nước sông là sự biến đổi dòng chảy theo thời gian, chịu ảnh hưởng nguồn cấp và điều kiện lưu vực. Mưa, băng tuyết tan, đất đá, địa hình, hồ và hoạt động con người đều có thể tham gia. Không phải mọi sông có cùng mùa nhiều nước.','A river regime describes changes in flow over time and reflects water sources and catchment conditions. Rain, snow or ice melt, geology, relief, lakes and human activity can all contribute. Rivers do not universally share the same high-flow season.','Khi giải thích một biểu đồ lưu lượng, cần biết vị trí trạm, thời kì và đặc điểm lưu vực thay vì chỉ đọc đỉnh biểu đồ.','Explaining a hydrograph requires the station, period and catchment context rather than the peak alone.'],
 ['Nước có vai trò đối với hệ sinh thái, sinh hoạt và các hoạt động sản xuất. Việc sử dụng nước cần cân nhắc chất lượng, trữ lượng, khả năng tái bổ sung và nhu cầu của các đối tượng khác. Các kho nước liên hệ khiến một tác động tại chỗ có thể lan sang nơi khác.','Water supports ecosystems, daily life and production. Its use requires attention to quality, storage, recharge and competing needs. Connections between reservoirs mean a local action may affect other places.','Thay đổi lớp phủ bề mặt có thể ảnh hưởng thấm, dòng chảy và chất lượng nước hạ lưu.','Changing surface cover can affect infiltration, runoff and downstream water quality.']
],
12:[
 ['Độ muối và nhiệt độ là những đặc tính quan trọng của nước biển và thay đổi theo không gian, thời gian. Bốc hơi, mưa, nguồn nước ngọt và trao đổi khối nước có thể ảnh hưởng độ muối. Đọc bản đồ cần kiểm tra tầng nước, thời kì và đơn vị của đại lượng.','Salinity and temperature are important seawater properties that vary through space and time. Evaporation, rainfall, freshwater inputs and water exchange can affect salinity. Check depth, period and units when reading a map.','Nơi nhận nhiều nước ngọt có thể có độ muối khác vùng bốc hơi mạnh; cần dữ liệu cụ thể để so sánh định lượng.','A freshwater-influenced area may differ in salinity from a strongly evaporative region; quantitative comparisons require data.'],
 ['Sóng mặt biển thông thường chủ yếu nhận năng lượng từ gió. Trong mô hình đơn giản, hạt nước dao động trong khi năng lượng truyền đi; không phải toàn bộ nước đi cùng đỉnh sóng tới bờ. Sóng thực còn phụ thuộc độ sâu và các điều kiện khác.','Ordinary surface waves mainly receive energy from wind. In a simple model, water particles oscillate while energy propagates; water does not simply travel with each crest to the shore. Actual waves also depend on depth and other conditions.','Đánh dấu một phao và một đỉnh sóng rồi so chuyển động của chúng. Mô hình giản lược không biểu hiện mọi dạng trôi dạt.','Mark a buoy and a wave crest, then compare their motion. The simplified model does not represent every kind of drift.'],
 ['Thủy triều là sự biến đổi có tính chu kì của mực nước biển liên quan tác động hấp dẫn của Mặt Trăng, Mặt Trời và động lực hệ. Đặc điểm triều tại một nơi còn phụ thuộc điều kiện địa phương. Sơ đồ vị trí thiên thể chỉ giúp học cơ chế khái quát.','Tides are cyclic sea-level changes related to lunar and solar gravity and the dynamics of the Earth system. Local tidal behaviour also depends on local conditions. A celestial-position diagram illustrates the broad mechanism only.','Không dùng bốn hình pha Mặt Trăng để tính chính xác giờ nước lớn tại một cảng; cần nguồn dự báo hoặc quan trắc phù hợp.','Four Moon-phase diagrams cannot determine exact high-tide times at a port; suitable predictions or observations are needed.'],
 ['Dòng biển là sự chuyển động có hướng của khối nước trong biển và đại dương ở quy mô đang xét. Các dòng góp phần phân bố lại nhiệt và có quan hệ với hệ thống khí hậu. Cần phân biệt chuyển động khối nước với dao động của sóng.','Ocean currents are directed movements of seawater at the scale being considered. They redistribute heat and interact with climate. The movement of a water mass should be distinguished from wave oscillation.','Bản đồ dòng nóng và dòng lạnh dùng mũi tên để thể hiện hướng khái quát; màu không cho biết nhiệt độ chính xác nếu thiếu thang đo.','Warm and cold current maps use arrows for general directions; colour alone does not provide precise temperatures without a scale.']
],
13:[
 ['Bảng lưu lượng tháng cho biết lưu lượng theo từng tháng tại một trạm và thời kì xác định. Lưu lượng thường dùng đơn vị m³/s, là thể tích qua mặt cắt trong một đơn vị thời gian. Cần kiểm tra nguồn, đơn vị và đủ các tháng trước khi tính chỉ số.','Monthly discharge tables describe river flow at a specified station and period. Discharge commonly uses m³/s, a volume passing a cross-section per unit time. Check the source, units and monthly completeness before calculating indicators.','DEMO-13 trong bài là chuỗi tự dựng để luyện thao tác, chưa phải quan trắc sông Hồng.','DEMO-13 is a synthetic practice series, not an observed Red River record.'],
 ['Nhận diện mùa nhiều nước và mùa ít nước cần cả chuỗi thời gian và một quy tắc được nêu rõ. Tháng cực đại không đại diện cho toàn bộ mùa. Đối với số liệu sông thật, kết luận phải gắn với trạm đo và thời kì.','Identifying high-flow and low-flow seasons requires the full time series and an explicit rule. The peak month does not define an entire season. For observed rivers, conclusions must remain tied to the station and period.','Trong thí nghiệm có thể tô các tháng vượt trung bình theo một quy tắc minh họa, nhưng không tự coi đó là định nghĩa duy nhất của mùa lũ.','The experiment may shade months above a mean using an illustrative rule, without presenting it as the only definition of a flood season.'],
 ['Chỉ số lưu lượng có thể gồm cực đại, cực tiểu, chênh lệch và tỉ số. Mỗi chỉ số cần công thức và đơn vị phù hợp. Cộng các giá trị lưu lượng tháng chưa cho thể tích nước năm; phép tính thể tích cần xét khoảng thời gian tương ứng.','Discharge indicators include maximum, minimum, range and ratios. Each needs an appropriate formula and unit. Summing monthly discharge values does not yield annual water volume; a volume calculation must account for time intervals.','Trong DEMO-13, chênh lệch là 6000−800=5200 m³/s và tỉ số là 6000/800=7,5 lần.','In DEMO-13, the range is 6000−800=5,200 m³/s and the ratio is 6000/800=7.5.'],
 ['Biểu đồ lưu lượng thể hiện sự biến đổi theo thời gian và hỗ trợ nhận xét về chế độ nước. Giải thích cần kết hợp đặc điểm nguồn cấp, khí hậu, lưu vực và điều tiết khi có dữ liệu. Không suy nguyên nhân duy nhất chỉ từ hình dạng đường biểu diễn.','A hydrograph shows flow variation over time and supports interpretation of a river regime. Explanations combine water sources, climate, catchment properties and regulation where data are available. The curve alone does not establish one unique cause.','Một nhận xét có căn cứ nêu tháng cực trị, mức chênh lệch, cách phân mùa và giới hạn dữ liệu.','An evidence-based interpretation states peak and minimum months, variation, the seasonal rule and data limitations.']
],
14:[
 ['Đất là hệ tự nhiên gồm thành phần khoáng, hữu cơ, nước, không khí và sinh vật. Các thành phần tương tác tạo nên đặc tính và chức năng của đất. Đất không chỉ là đá vụn khô, cũng không phải vật liệu đồng nhất ở mọi nơi.','Soil is a natural system containing minerals, organic matter, water, air and living organisms. Their interactions produce soil properties and functions. Soil is neither merely dry rock fragments nor a uniform material everywhere.','Quan sát mẫu cần chú ý cấu tạo, độ ẩm và chất hữu cơ, thay vì chỉ phân biệt bằng màu sắc.','Observe texture, moisture and organic material rather than relying only on colour.'],
 ['Đất hình thành dưới tác động tổng hợp của đá mẹ, khí hậu, sinh vật, địa hình, thời gian và con người. Đá mẹ cung cấp vật liệu khoáng ban đầu, nhưng không quyết định một mình mọi đặc điểm. Cùng đá mẹ vẫn có thể hình thành đất khác nhau nếu các nhân tố khác khác nhau.','Soil formation reflects parent material, climate, organisms, relief, time and human activity together. Parent material supplies initial minerals but does not independently determine all properties. Similar parent material can produce different soils under different conditions.','Giữ đá mẹ rồi so hai kịch bản khác khí hậu hoặc sinh vật để xem cách các nhân tố phối hợp.','Keep parent material fixed and compare scenarios with different climates or organisms to explore interacting factors.'],
 ['Phẫu diện đất là mặt cắt thể hiện các tầng đất theo chiều sâu. Số tầng và đặc điểm từng tầng phụ thuộc loại đất cùng quá trình hình thành. Một sơ đồ đại diện giúp học cách đọc nhưng không thể dùng để khẳng định mọi phẫu diện giống nhau.','A soil profile is a vertical section showing soil horizons. Their number and properties depend on soil type and formation processes. A representative diagram teaches profile reading but does not imply that every soil profile is identical.','Chọn một tầng để đọc thành phần và vai trò; nhãn cần được đối chiếu với phẫu diện cụ thể.','Select a horizon to read its constituents and role; labels must be interpreted within the particular profile.'],
 ['Các nhóm đất có đặc điểm và sự phân bố liên hệ với điều kiện hình thành. Bản đồ đất sử dụng một hệ phân loại cụ thể, cần đọc tên nhóm và định nghĩa thay vì chỉ so màu. Tỉ lệ bản đồ giới hạn mức chi tiết có thể suy luận.','Soil groups have properties and distributions related to formation conditions. A soil map follows a classification system; read group definitions rather than matching colours alone. Map scale limits the detail that can be inferred.','Hai bản đồ cùng màu nâu có thể dùng màu cho hai nhóm khác nhau nếu chú giải khác nhau.','Two maps may use the same brown colour for different soil groups when their legends differ.'],
 ['Đất hỗ trợ sinh vật, lưu giữ và điều tiết nước, đồng thời phục vụ nhiều hoạt động của con người. Bảo vệ đất cần giảm những tác động vượt khả năng duy trì chức năng của đất. Biện pháp phù hợp phải xét địa hình, khí hậu, lớp phủ và cách sử dụng.','Soil supports organisms, stores and regulates water, and enables many human activities. Conservation aims to prevent pressures that undermine these functions. Suitable measures depend on relief, climate, cover and land use.','Duy trì che phủ phù hợp trên sườn dốc có thể góp phần hạn chế xói mòn; hiệu quả cụ thể cần được đánh giá theo điều kiện thực.','Maintaining suitable cover on a slope can help limit erosion; actual effectiveness depends on local conditions.']
],
15:[
 ['Sinh quyển gắn với sự sống và những phần của Trái Đất có sinh vật tồn tại. Nó có liên hệ với khí quyển, thủy quyển và phần bề mặt đất đá. Sinh quyển không chỉ gồm sinh vật trên đất liền.','The biosphere concerns life and the parts of Earth where organisms occur. It interacts with the atmosphere, hydrosphere and near-surface solid Earth. It is not limited to life on land.','Sự sống ở nước cũng thuộc phạm vi nghiên cứu sinh quyển, với các điều kiện môi trường riêng.','Aquatic life belongs within the biosphere and depends on its own environmental conditions.'],
 ['Sự phát triển và phân bố sinh vật chịu tác động phối hợp của nhiệt, ẩm, đất, địa hình và các yếu tố khác. Lịch sử và tác động của con người cũng có vai trò. Không thể dùng một giá trị nhiệt độ để giải thích mọi sự phân bố.','Organism growth and distribution reflect temperature, moisture, soils, relief and other influences together. History and human activity also matter. A single temperature value cannot explain all distribution patterns.','Hai môi trường cùng nhiệt độ nhưng khác độ ẩm có thể phù hợp với những thảm thực vật khác nhau.','Environments with equal temperatures but different moisture conditions may support different vegetation.'],
 ['Khí hậu, đất và địa hình tạo những điều kiện sống có liên hệ với nhau. Địa hình có thể làm thay đổi nhiệt, ẩm và đất, qua đó tác động đến sinh vật. Khi so sánh, cần ghi rõ các điều kiện thay vì ghép một loài vào một yếu tố duy nhất.','Climate, soils and relief provide interconnected living conditions. Relief can alter temperature, moisture and soil conditions and thereby influence organisms. Comparisons should document these conditions rather than linking a species to one factor alone.','So một sườn ẩm với một sườn khô ở vị trí gần nhau có thể gợi ý vai trò của điều kiện địa hình và ẩm.','Comparing nearby moist and dry slopes can suggest the roles of relief and moisture.'],
 ['Sinh vật có phân bố không đồng đều và tham gia các quá trình trao đổi vật chất trong hệ tự nhiên. Thảm thực vật có liên hệ với đất và nước, đồng thời chịu tác động từ sử dụng đất. Bảo vệ sinh cảnh giúp duy trì điều kiện tồn tại của các quần xã.','Organisms are unevenly distributed and participate in material exchanges within natural systems. Vegetation interacts with soils and water and responds to land use. Habitat conservation helps sustain the conditions needed by communities.','Thay đổi lớp phủ thực vật có thể ảnh hưởng bảo vệ đất và dòng chảy, tạo liên hệ tới các bài về thủy quyển và vỏ địa lí.','Vegetation-cover change can affect soil protection and runoff, linking this topic to the hydrosphere and geographical envelope.']
],
16:[
 ['Đọc bản đồ đất cần xác định hệ phân loại, phạm vi, tỉ lệ và chú giải. Tên nhóm trên các nguồn khác nhau có thể không hoàn toàn tương đương. Việc đối chiếu phải dựa trên định nghĩa và thông tin nguồn.','Reading a soil map requires its classification, extent, scale and legend. Group names in different sources may not be fully equivalent. Comparisons should use definitions and source information.','Ghi tên nhóm đất của vùng A và B vào bảng trước khi giải thích mối liên hệ với sinh vật.','Record the soil groups of regions A and B in a table before discussing their links with vegetation.'],
 ['Bản đồ sinh vật hoặc thảm thực vật thể hiện đối tượng theo cách phân loại và thời điểm cụ thể. Không được coi thảm thực vật hiện tại luôn giống thảm thực vật tự nhiên tiềm năng. Cần kiểm tra bản đồ đang mô tả điều gì.','An organism or vegetation map represents features within a classification and time context. Current vegetation should not automatically be treated as potential natural vegetation. Check exactly what the map describes.','Lớp cây trồng phản ánh sử dụng đất, còn một bản đồ quần xã tự nhiên có mục đích biểu hiện khác.','A crop layer describes land use, whereas a map of natural communities represents a different subject.'],
 ['So sánh vùng cần cùng bộ tiêu chí như đất, thảm thực vật, nhiệt và ẩm. Ghi dữ liệu từ từng lớp vào bảng rồi chỉ ra điểm giống và khác có dẫn chứng. Nếu khác hệ phân loại, cần ánh xạ hợp lí trước khi so.','Regional comparisons require shared criteria such as soils, vegetation, temperature and moisture. Record layer attributes in a table and use them to identify similarities and differences. Different classification systems need justified alignment.','Chọn A và B rồi bật các lớp lần lượt để tránh bỏ sót thuộc tính hoặc nhầm chú giải.','Select A and B, then enable layers in turn to avoid missing attributes or confusing their legends.'],
 ['Giải thích quan hệ đất–sinh vật cần xem đồng thời khí hậu, địa hình và tác động con người. Sự trùng vùng cho thấy liên hệ không gian nhưng chưa chứng minh một nguyên nhân duy nhất. Ngoại lệ có thể đến từ thực tế hoặc giới hạn dữ liệu và cần được kiểm tra.','Explaining soil–vegetation relationships also requires climate, relief and human activity. Spatial overlap indicates association but does not prove a single cause. Exceptions may reflect real conditions or data limitations and should be investigated.','Với một vùng khác xu hướng chung, kiểm nguồn, thời điểm và mức chi tiết trước khi đặt giả thuyết về nguyên nhân.','For a region that differs from the general pattern, check source, date and detail before proposing an explanation.']
],
17:[
 ['Vỏ địa lí được nghiên cứu như một hệ các thành phần tự nhiên có quan hệ và trao đổi với nhau. Khi xem xét một khu vực, cần kết hợp không khí, nước, đất đá, sinh vật và các quá trình liên quan. Một thành phần riêng lẻ không đại diện đầy đủ cho toàn hệ.','The geographical envelope is studied as a system of interacting natural components and exchanges. Investigating an area requires air, water, soil and rock, organisms and related processes together. A single component does not represent the entire system.','Một lưu vực có thể được dùng làm tình huống để theo dõi các mối liên hệ giữa mưa, lớp phủ, đất và dòng chảy.','A catchment provides a setting for tracing relationships among rainfall, cover, soils and runoff.'],
 ['Các thành phần tự nhiên vừa chịu tác động vừa có thể tác động ngược lại những thành phần khác. Nước ảnh hưởng đất và sinh vật; sinh vật cũng ảnh hưởng giữ nước và bảo vệ đất. Quan hệ thường phụ thuộc điều kiện và quy mô đang xét.','Natural components both respond to and influence one another. Water affects soils and organisms, while organisms affect water retention and soil protection. Relationships depend on conditions and the scale considered.','Một sơ đồ mũi tên hai chiều có thể diễn tả tác động qua lại, nhưng mỗi cạnh cần một giải thích cơ chế.','A two-way arrow diagram can represent reciprocal effects, but each connection needs a mechanism.'],
 ['Quy luật thống nhất và hoàn chỉnh nhấn mạnh sự gắn bó giữa các thành phần trong vỏ địa lí. Thay đổi ở một thành phần có thể kéo theo thay đổi ở các thành phần khác. Điều này không có nghĩa mọi tác động đều tức thì, tuyến tính hoặc cùng mức độ.','The principle of unity and integrity emphasises connections among components of the geographical envelope. A change in one can lead to changes in others. This does not imply that every effect is immediate, linear or equally strong.','Giảm lớp phủ có thể làm thay đổi thấm và chảy tràn; mức tác động còn phụ thuộc mưa, dốc và đặc tính đất.','Reduced cover can alter infiltration and runoff; the magnitude also depends on rain, slope and soil properties.'],
 ['Chuỗi nguyên nhân–hệ quả cần nêu biến ban đầu, các mắt xích trung gian và kết quả. Mỗi liên hệ phải có cơ chế cùng điều kiện áp dụng. Mô hình định tính hỗ trợ lập luận, không đủ để dự báo chính xác thiệt hại của một lưu vực thực.','A cause-and-effect chain identifies an initial change, intermediate links and outcomes. Every link needs a mechanism and applicable conditions. A qualitative model supports reasoning but cannot precisely forecast damage in an actual catchment.','Giảm che phủ → giảm bảo vệ đất → tăng xói mòn trong điều kiện phù hợp → tăng vật liệu về hạ lưu.','Reduced cover → less soil protection → increased erosion under suitable conditions → more sediment downstream.']
],
18:[
 ['Quy luật địa đới biểu hiện sự phân hóa tự nhiên có tính quy luật theo vĩ độ. Sự khác biệt năng lượng bức xạ là cơ sở quan trọng, nhưng biểu hiện thực còn chịu tác động của các yếu tố khác. Cần so theo trục vĩ độ thay vì gọi mọi sự khác biệt là địa đới.','Latitudinal zonality describes systematic natural differentiation with latitude. Differences in solar energy are important, but actual patterns are modified by other factors. Compare along latitude rather than calling every difference zonality.','So hai vị trí khác vĩ độ ở độ cao gần tương đương và ghi các điều kiện chưa kiểm soát được.','Compare locations at different latitudes and similar elevations, documenting conditions that remain uncontrolled.'],
 ['Quy luật phi địa đới gắn với phân hóa tự nhiên không đơn thuần theo vĩ độ, như ảnh hưởng độ cao và sự phân bố lục địa–đại dương. Trong thực tế, địa đới và phi địa đới cùng tác động. Phân tích cần xác định nhân tố đang được thay đổi.','Azonality concerns differentiation that does not simply follow latitude, including elevation and land–ocean influences. Zonal and azonal effects operate together in real landscapes. Analysis should identify the factor being varied.','Một lát cắt từ ven biển vào nội địa giữ gần cùng vĩ độ giúp thảo luận ảnh hưởng vị trí lục địa.','A coast-to-interior transect at similar latitude helps explore continental position.'],
 ['Đai cao là sự phân hóa tự nhiên theo độ cao trong điều kiện một khu vực núi. Nhiệt, ẩm, đất và sinh vật có thể thay đổi theo sườn và cao độ. Mốc cùng thành phần đai còn phụ thuộc vĩ độ, hướng sườn và điều kiện địa phương.','Altitudinal zonation is natural differentiation with elevation in a mountain region. Temperature, moisture, soils and vegetation may change with slope and altitude. Belt limits and composition also depend on latitude, aspect and local conditions.','Không dùng mốc đai của một núi để khẳng định mọi núi có cùng thảm thực vật ở cùng cao độ.','Belt limits on one mountain cannot establish that all mountains have identical vegetation at the same elevation.'],
 ['Vị trí gần biển hay sâu trong lục địa có thể làm thay đổi ảnh hưởng của đại dương và các điều kiện nhiệt, ẩm. Sự phân hóa còn kết hợp với địa hình và hoàn lưu. Cần đối chiếu nhiều thông tin thay vì chỉ dùng khoảng cách tới bờ làm đáp án duy nhất.','Coastal or interior position can alter oceanic influences and thermal or moisture conditions. Relief and circulation also shape the pattern. Several sources of evidence are needed rather than distance from the coast alone.','So hai điểm gần cùng vĩ độ, ghi vị trí biển–lục địa và địa hình rồi giải thích các khác biệt có điều kiện.','Compare points at similar latitude, record their coast–interior position and relief, and explain differences conditionally.']
]};
